export default "l_reactivity.json`\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"reference_sources/DBT+ADHD Skill Files/12_ADHD_Burnout_Sensory_and_Self_Help/README.md\",\"language\":\"md\",\"content\":\"# 12 ADHD Burnout Sensory and Self Help\\n\\nADHD burnout recovery, sensory overload support, workbook, and self-help pack.\\n\\n## Counts\\n\\n- HTML: 2\\n- JSON: 4\\n\\n## Files\\n\\n- `html/adhd_self_help_resource_pack.html`\\n- `html/adhd_workbook.html`\\n- `json/adhd_burnout_recovery_neurodivergent_insights.json`\\n- `json/adhd_self_help_resource_pack.json`\\n- `json/adhd_workbook.json`\\n- `json/overstimulated_by_life_20_ways_to_give_your_adhd_senses_a_break.json`\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"reference_sources/DBT+ADHD Skill Files/03_DBT_Interpersonal_Effectiveness/README.md\",\"language\":\"md\",\"content\":\"# 03 DBT Interpersonal Effectiveness\\n\\nDBT interpersonal effectiveness handouts, scripts, checklists, and worksheets.\\n\\n## Counts\\n\\n- HTML: 17\\n- JSON: 51\\n\\n## Files\\n\\n- `handouts/json/interpersonal_effectiveness_handout_10_overview_building_relationships_and_ending_destructive_ones_finding_an.json`\\n- `handouts/json/interpersonal_effectiveness_handout_11_finding_and_getting_people_to_like_you_remember_all_human_beings_are_l.json`\\n- `handouts/json/interpersonal_effectiveness_handout_11a_identifying_skills_to_find_people_and_get_them_to_like_you_for_each_a.json`\\n- `handouts/json/interpersonal_effectiveness_handout_12_mindfulness_of_others_friendships_last_longer_when_we_are_mindful_obse.json`\\n- `handouts/json/interpersonal_effectiveness_handout_12a_identifying_mindfulness_of_others_for_each_a_and_b_pair_check_the_more.json`\\n- `handouts/json/interpersonal_effectiveness_handout_13_ending_relationships_a_destructive_relationship_has_the_quality_of_des.json`\\n- `handouts/json/interpersonal_effectiveness_handout_13a_identifying_how_to_end_relationships_for_each_a_and_b_pair_check_the_m.json`\\n- `handouts/json/interpersonal_effectiveness_handout_14_overview_walking_the_middle_path_balancing_acceptance_and_change_diale.json`\\n- `handouts/json/interpersonal_effectiveness_handout_15_dialectics_dialectics_reminds_us_that.json`\\n- `handouts/json/interpersonal_effectiveness_handout_16_1_there_is_always_more_than_one_side_to_anything_that_exists_look_for.json`\\n- `handouts/json/interpersonal_effectiveness_handout_16a_examples_of_opposite_sides_that_can_both_be_true_1_you_can_want_to_cha.json`\\n- `handouts/json/interpersonal_effectiveness_handout_16b_important_opposites_to_balance_1_accepting_reality_and_working_to_chan.json`\\n- `handouts/json/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_group_check_the_most_dialectical_respo.json`\\n- `handouts/json/interpersonal_effectiveness_handout_17_validation_validation_means.json`\\n- `handouts/json/interpersonal_effectiveness_handout_18_a_how_to_guide_to_validation.json`\\n- `handouts/json/interpersonal_effectiveness_handout_18a_identifying_validation_for_each_a_and_b_pair_check_the_more_effective.json`\\n- `handouts/json/interpersonal_effectiveness_handout_19_recovering_from_invalidation_notice_that_invalidation_can_be_helpful_a.json`\\n- `handouts/json/interpersonal_effectiveness_handout_19a_identifying_self_validation_for_each_a_and_b_pair_check_the_more_effec.json`\\n- `handouts/json/interpersonal_effectiveness_handout_1_goals_of_interpersonal_effectiveness_be_skillful_in_getting_what_you_w.json`\\n- `handouts/json/interpersonal_effectiveness_handout_20_strategies_for_increasing_the_probability_of_behaviors_you_want.json`\\n- `handouts/json/interpersonal_effectiveness_handout_21_strategies_for_decreasing_or_stopping_unwanted_behaviors_extinction_st.json`\\n- `handouts/json/interpersonal_effectiveness_handout_22_tips_for_using_behavior_change_strategies_effectively_summary_so_far_g.json`\\n- `handouts/json/interpersonal_effectiveness_handout_22a_identifying_effective_behavior_change_strategies_for_each_a_and_b_pair.json`\\n- `handouts/json/interpersonal_effectiveness_handout_2_factors_in_the_way_of_interpersonal_effectiveness_you_don_t_have_the_i.json`\\n- `handouts/json/interpersonal_effectiveness_handout_2a_myths_in_the_way_of_interpersonal_effectiveness_myths_in_the_way_of_ob.json`\\n- `handouts/json/interpersonal_effectiveness_handout_3_overview_obtaining_objectives_skillfully_clarifying_priorities.json`\\n- `handouts/json/interpersonal_effectiveness_handout_4_clarifying_goals_in_interpersonal_situations_objectives_effectiveness.json`\\n- `handouts/json/interpersonal_effectiveness_handout_5_guidelines_for_objectives_effectiveness_getting_what_you_want_dear_man.json`\\n- `handouts/json/interpersonal_effectiveness_handout_5a_applying_dear_man_skills_to_a_difficult_current_interaction.json`\\n- `handouts/json/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effectiveness_keeping_the_relationship_giv.json`\\n- `handouts/json/interpersonal_effectiveness_handout_6a_expanding_the_v_in_give_levels_of_validation.json`\\n- `handouts/json/interpersonal_effectiveness_handout_7_guidelines_for_self_respect_effectiveness_keeping_respect_for_yourself.json`\\n- `handouts/json/interpersonal_effectiveness_handout_8_evaluating_options_for_whether_or_how_intensely_to_ask_for_something_o.json`\\n- `handouts/json/interpersonal_effectiveness_handout_9_troubleshooting.json`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_10_ending_relationships.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_11_practicing_dialectics.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_11a_dialectics_checklist.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_11b_noticing_when_you_re_not_dialectical.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_12_validating_others.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_13_self_validation_and_self_respect.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_14_changing_behavior_with_reinforcement.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_15_changing_behavior_by_extinguishing_or_punishing_it.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_1_pros_and_cons_of_using_interpersonal_effectiveness_skills.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_2_challenging_myths_in_the_way_of_obtaining_objectives_challenging_myths.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_3_clarifying_priorities_in_interpersonal_situations.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_4_writing_out_interpersonal_effectiveness_scripts.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_5_tracking_interpersonal_effectiveness_skills_use.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_6_the_dime_game_figuring_out_how_strongly_to_ask_or_say_no.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_7_troubleshooting_interpersonal_effectiveness_skills.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_8_finding_and_getting_people_to_like_you.html`\\n- `worksheets/html/interpersonal_effectiveness_worksheet_9_mindfulness_of_others.html`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_10_ending_relationships.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_11_practicing_dialectics.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_11a_dialectics_checklist.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_11b_noticing_when_you_re_not_dialectical.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_12_validating_others.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_13_self_validation_and_self_respect.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_14_changing_behavior_with_reinforcement.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_15_changing_behavior_by_extinguishing_or_punishing_it.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_1_pros_and_cons_of_using_interpersonal_effectiveness_skills.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_2_challenging_myths_in_the_way_of_obtaining_objectives_challenging_myths.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_3_clarifying_priorities_in_interpersonal_situations.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_4_writing_out_interpersonal_effectiveness_scripts.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_5_tracking_interpersonal_effectiveness_skills_use.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_6_the_dime_game_figuring_out_how_strongly_to_ask_or_say_no.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_7_troubleshooting_interpersonal_effectiveness_skills.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_8_finding_and_getting_people_to_like_you.json`\\n- `worksheets/json/interpersonal_effectiveness_worksheet_9_mindfulness_of_others.json`\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"reference_sources/DBT+ADHD Skill Files/13_ADHD_General_Reference_and_Diagnosis/README.md\",\"language\":\"md\",\"content\":\"# 13 ADHD General Reference and Diagnosis\\n\\nADHD general reference, diagnosis, and treatment professional information.\\n\\n## Counts\\n\\n- JSON: 1\\n\\n## Files\\n\\n- `json/the_professionals_who_diagnose_and_treat_adhd.json`\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"reference_sources/DBT+ADHD Skill Files/07_DBT_Indexes_and_Compact_Exports/README.md\",\"language\":\"md\",\"content\":\"# 07 DBT Indexes and Compact Exports\\n\\nCompact DBT item export and DBT skill index.\\n\\n## Counts\\n\\n- JSON: 2\\n\\n## Files\\n\\n- `json/all_items_compact.json`\\n- `json/dbt_skills_index.json`\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"psychiatrypt2.gs\",\"language\":\"gs\",\"content\":\"/**\\n * psychiatrypt2.gs\\n * Merge-friendly Apps Script module for the Unified Psychiatric AI Brain Part 2.\\n *\\n * Required Script Property: OPENAI_API_KEY\\n * Optional: OPENAI_MODEL, PSY2_KNOWLEDGE_BASE_URL, PSY2_US_988_ENABLED\\n *\\n * This file intentionally does NOT define global doGet/doPost, so it can be\\n * combined with other backend modules without entry-point collisions.\\n */\\nvar PsychiatryPt2 = (function () {\\n  'use strict';\\n\\n  var VERSION = '2.0.0';\\n  var DEFAULT_MODEL = 'gpt-5';\\n  var DEFAULT_KNOWLEDGE_ROOT = 'https://raw.githubusercontent.com/tyrannosaurusdm92/AI-Brain project/main/AI-Brain/json/psychiatry2';\\n  var RESPONSES_URL = 'https://api.openai.com/v1/responses';\\n  var MODERATION_URL = 'https://api.openai.com/v1/moderations';\\n\\n  function props_() { return PropertiesService.getScriptProperties(); }\\n  function cfg_(name, fallback) { var v = props_().getProperty(name); return v === null || v === '' ? fallback : v; }\\n  function bool_(name, fallback) { var v = String(cfg_(name, fallback ? 'true' : 'false')).toLowerCase(); return v === 'true' || v === '1' || v === 'yes'; }\\n  function apiKey_() { var k = cfg_('OPENAI_API_KEY', ''); if (!k) throw new Error('OPENAI_API_KEY is not configured'); return k; }\\n  function model_() { return cfg_('OPENAI_MODEL', DEFAULT_MODEL); }\\n  function knowledgeRoot_() { return String(cfg_('PSY2_KNOWLEDGE_BASE_URL', DEFAULT_KNOWLEDGE_ROOT)).replace(/\\\\/$/, ''); }\\n\\n  function jsonOutput_(obj, code) {\\n    var out = ContentService.createTextOutput(JSON.stringify(obj));\\n    out.setMimeType(ContentService.MimeType.JSON);\\n    return out;\\n  }\\n\\n  function parseBody_(e) {\\n    if (!e || !e.postData || !e.postData.contents) return {};\\n    try { return JSON.parse(e.postData.contents); } catch (err) { return { message: e.postData.contents }; }\\n  }\\n\\n  function normalize_(v) { return String(v == null ? '' : v).replace(/\\\\s+/g, ' ').trim(); }\\n\\n  function assessRisk_(message) {\\n    var t = normalize_(message);\\n    var rules = {\\n      selfHarmIntent: /(i (?:want|plan|intend|am going) to (?:die|kill myself|end my life)|suicide plan|i can(?:not|'t) stay safe|i have the (?:pills|gun|weapon|means))/i,\\n      selfHarmConcern: /(suicid|self[- ]?harm|cut myself|wish i were dead|don(?:'t| not) want to be alive)/i,\\n      violenceIntent: /(i (?:want|plan|intend|am going) to (?:kill|shoot|stab|hurt) (?:him|her|them|someone|people)|homicid)/i,\\n      overdose: /(overdose|took too many|double dose|swallowed a bottle|poisoning)/i,\\n      severeBreathing: /(can(?:not|'t) breathe|stopped breathing|severe shortness of breath|blue lips|turning blue)/i,\\n      severeChest: /(severe chest (?:pain|pressure)|crushing chest|chest pain.*(?:sweat|shortness of breath|dizz|nausea))/i,\\n      strokeLike: /(face droop|sudden.*(?:arm|leg).*weak|sudden.*slurred speech|suddenly can(?:not|'t) speak)/i,\\n      alteredMentalStatus: /(unresponsive|won(?:'t| not) wake|sudden confusion)/i,\\n      severeAllergy: /(anaphyl|throat closing|severe allergic.*(?:breath|swelling))/i\\n    };\\n    var hits = [];\\n    Object.keys(rules).forEach(function (k) { if (rules[k].test(t)) hits.push(k); });\\n    var emergencyKeys = ['selfHarmIntent','violenceIntent','overdose','severeBreathing','severeChest','strokeLike','alteredMentalStatus','severeAllergy'];\\n    var emergency = hits.some(function (h) { return emergencyKeys.indexOf(h) >= 0; });\\n    return { emergency: emergency, elevated: emergency || hits.indexOf('selfHarmConcern') >= 0, hits: hits };\\n  }\\n\\n  function route_(message, context) {\\n    var t = normalize_(message).toLowerCase();\\n    var routes = [];\\n    function add(name, re, score) { if (re.test(t)) routes.push({ name:name, score:score }); }\\n    add('crisis', /(suicid|kill myself|end my life|self[- ]?harm|overdose|hurt someone|kill someone)/i, 100);\\n    add('physical_health', /(chest pain|breath|faint|seizure|stroke|oxygen|pain|fever|vomit|diarrhea|medical|symptom|mobility|fatigue)/i, 45);\\n    add('autism', /(autis|sensory|meltdown|shutdown|masking|routine change|interoception)/i, 35);\\n    add('adhd', /(adhd|executive function|time blindness|procrastinat|task initiation|hyperfocus|body doubl|working memory)/i, 35);\\n    add('dbt', /(dbt|distress tolerance|wise mind|opposite action|dear man|emotion regulation|chain analysis|radical acceptance|tipp)/i, 30);\\n    add('cbt', /(cbt|thought record|cognitive distort|behavioral activation|automatic thought|exposure|reframe|core belief)/i, 30);\\n    add('psychiatric', /(psychiatr|medication|antidepress|antipsych|mood stabil|mania|psychosis|hallucin|paranoi|ocd|ptsd|depression|anxiety|panic)/i, 30);\\n    add('sleep', /(sleep|insomnia|nightmare|bedtime|circadian)/i, 18);\\n    add('care_coordination', /(appointment|doctor|therapist|psychiatrist|clinician|provider|care plan)/i, 16);\\n    if (context && context.supportAreas && context.supportAreas.length) context.supportAreas.forEach(function (x) { routes.push({name:String(x),score:12}); });\\n    routes.sort(function (a,b) { return b.score-a.score; });\\n    var cats=[]; routes.forEach(function(r){if(cats.indexOf(r.name)<0) cats.push(r.name);});\\n    if(!cats.length) cats=['general_mental_health'];\\n    return { primary:cats[0], categories:cats.slice(0,5), scored:routes };\\n  }\\n\\n  function fetchJson_(relativePath) {\\n    var cache = CacheService.getScriptCache();\\n    var key = 'psy2:' + relativePath;\\n    var cached = cache.get(key);\\n    if (cached) try { return JSON.parse(cached); } catch (e) {}\\n    var res = UrlFetchApp.fetch(knowledgeRoot_() + '/' + relativePath, { muteHttpExceptions:true });\\n    if (res.getResponseCode() < 200 || res.getResponseCode() >= 300) throw new Error('Knowledge fetch failed: ' + relativePath + ' (' + res.getResponseCode() + ')');\\n    var text = res.getContentText();\\n    if (text.length < 95000) cache.put(key, text, 600);\\n    return JSON.parse(text);\\n  }\\n\\n  function tokenize_(s) { return normalize_(s).toLowerCase().split(/[^a-z0-9+_-]+/).filter(function(x){return x.length>1;}); }\\n  function scoreCard_(card, query) {\\n    var q={}; tokenize_(query).forEach(function(t){q[t]=1;});\\n    var body=[card.title||'',(card.tags||[]).join(' '),card.when_to_use||'',card.summary||''].join(' ');\\n    return tokenize_(body).reduce(function(sum,t){return sum+(q[t]?1:0);},0);\\n  }\\n\\n  function loadCards_(message, route) {\\n    var manifest = fetchJson_('manifest.json');\\n    var all=[];\\n    route.categories.forEach(function(cat){\\n      var file = manifest.categories[cat] || manifest.categories.general_mental_health;\\n      if (!file) return;\\n      var pack = fetchJson_(file);\\n      (pack.cards||[]).forEach(function(c){ var copy=JSON.parse(JSON.stringify(c)); copy._category=cat; copy._score=scoreCard_(copy,message); all.push(copy); });\\n    });\\n    all.sort(function(a,b){return b._score-a._score;});\\n    return all.slice(0,8);\\n  }\\n\\n  function accessibility_(profile) {\\n    profile=profile||{}; var out=[];\\n    if(profile.lowEnergy) out.push('Use very small steps and offer a minimum-effort option first.');\\n    if(profile.cognitiveLoad==='low') out.push('Keep to 1-3 steps at a time and avoid dense option lists.');\\n    if(profile.mobilityLimited) out.push('Do not assume standing, walking, exercise, or showering is available; offer seated/lying-down alternatives.');\\n    if(profile.sensorySensitive) out.push('Do not assume breathing exercises, cold exposure, music, touch, or bright sensory input is soothing.');\\n    if(profile.communication==='literal') out.push('Use concrete literal wording.');\\n    if(profile.communication==='minimal') out.push('Allow yes/no, scale, multiple-choice, or one-word replies.');\\n    return out;\\n  }\\n\\n  function developerInstructions_(route, cards, context, risk) {\\n    var parts=[\\n      'You are a supportive mental-health, psychiatric-support, neurodivergence-support, and disability-support assistant using a structured knowledge layer.',\\n      'Do not claim to diagnose, prescribe, replace a clinician, or guarantee that symptoms are harmless.',\\n      'Use collaborative, autonomy-respecting language. Ask only questions that materially change the next safe step.',\\n      'Do not treat autism or ADHD as moral failures. Do not encourage masking as the default goal.',\\n      'For medication questions, organize observations and questions; direct starts/stops/dose/taper decisions to a prescriber or pharmacist.',\\n      risk.emergency ? 'EMERGENCY ROUTE: prioritize immediate safety and local emergency/crisis connection. Do not bury this under coping skills.' : 'Use skills coaching only when it fits the user goal and safety state.',\\n      'Primary route: ' + route.primary + '.'\\n    ].concat(accessibility_(context && context.accessibility));\\n    if(cards.length){\\n      parts.push('Relevant support cards:');\\n      cards.forEach(function(c,i){ parts.push('['+(i+1)+'] '+c.title+': '+c.summary+' | Use: '+(c.when_to_use||'as relevant')+' | Cautions: '+(c.cautions||[]).join('; ')); });\\n    }\\n    return parts.join('\\\\n');\\n  }\\n\\n  function emergencyText_(context) {\\n    var text='This could be an emergency. If there is immediate danger, a possible overdose, severe breathing trouble, severe chest pain/pressure, sudden stroke-like symptoms, or someone cannot be kept safe, contact your local emergency service or go to the nearest emergency department now. If possible, involve a trusted person and move away from immediate hazards while help is contacted.';\\n    if (bool_('PSY2_US_988_ENABLED', false) && context && String(context.country||'').toUpperCase()==='US') text += ' In the United States, call or text 988 for suicide, mental-health, or substance-use crisis support; use 911 for life-threatening emergencies.';\\n    return text;\\n  }\\n\\n  function openAiPost_(url, payload) {\\n    var res = UrlFetchApp.fetch(url, { method:'post', contentType:'application/json', headers:{Authorization:'Bearer '+apiKey_()}, payload:JSON.stringify(payload), muteHttpExceptions:true });\\n    var body=res.getContentText(); var parsed; try{parsed=JSON.parse(body);}catch(e){parsed={raw:body};}\\n    if(res.getResponseCode()<200||res.getResponseCode()>=300) throw new Error('OpenAI request failed ('+res.getResponseCode()+'): '+body.slice(0,1200));\\n    return parsed;\\n  }\\n\\n  function moderate_(message) {\\n    try { return openAiPost_(MODERATION_URL,{model:'omni-moderation-latest',input:message}); }\\n    catch(e){ return {error:String(e),results:[]}; }\\n  }\\n\\n  function extractText_(response) {\\n    if(response.output_text) return response.output_text;\\n    var chunks=[];\\n    (response.output||[]).forEach(function(item){(item.content||[]).forEach(function(c){if(c.type==='output_text'&&c.text)chunks.push(c.text);});});\\n    return chunks.join('\\\\n').trim();\\n  }\\n\\n  function chat(input) {\\n    input=input||{}; var message=normalize_(input.message); if(!message) throw new Error('message is required');\\n    var context=input.context||{}; var risk=assessRisk_(message); var route=route_(message,context);\\n    if(risk.emergency){\\n      return {ok:true,module:'psychiatry2',version:VERSION,route:route,risk:risk,answer:emergencyText_(context),emergency:true};\\n    }\\n    var cards=[]; try{cards=loadCards_(message,route);}catch(e){cards=[];}\\n    var moderation=moderate_(message);\\n    var instructions=developerInstructions_(route,cards,context,risk);\\n    var response=openAiPost_(RESPONSES_URL,{model:model_(),instructions:instructions,input:[{role:'user',content:[{type:'input_text',text:message}]}],store:false,metadata:{module:'psychiatry2',route:route.primary}});\\n    return {ok:true,module:'psychiatry2',version:VERSION,route:route,risk:risk,moderation:moderation,knowledge_cards:cards.map(function(c){return c.id;}),answer:extractText_(response),response_id:response.id||null};\\n  }\\n\\n  function handlePost(e) {\\n    try {\\n      var body=parseBody_(e); var action=body.action||'chat';\\n      if(action==='chat') return jsonOutput_(chat(body));\\n      if(action==='route') return jsonOutput_({ok:true,module:'psychiatry2',version:VERSION,route:route_(body.message||'',body.context||{}),risk:assessRisk_(body.message||'')});\\n      if(action==='health') return jsonOutput_(health());\\n      return jsonOutput_({ok:false,error:'Unknown psychiatry2 action: '+action});\\n    } catch(err) { return jsonOutput_({ok:false,module:'psychiatry2',error:String(err && err.message ? err.message : err)}); }\\n  }\\n\\n  function handleGet(e) { return jsonOutput_(health()); }\\n  function health() { return {ok:true,module:'psychiatry2',version:VERSION,model:model_(),knowledge_root:knowledgeRoot_(),api_key_configured:Boolean(cfg_('OPENAI_API_KEY',''))}; }\\n\\n  return { version:VERSION, chat:chat, handlePost:handlePost, handleGet:handleGet, health:health, assessRisk:assessRisk_, route:route_ };\\n})();\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"README.md\",\"language\":\"md\",\"content\":\"# Unified Psychiatric AI Brain \u2014 Part 2\\n\\nA consolidated, **non-personalized** support intelligence package for ADHD, autism, CBT, DBT, psychiatric support, mental-health support, disability/accessibility support, and general physical-health support. It is intended to be used as a knowledge-and-routing layer behind an AI service, not as an autonomous clinician.\\n\\n## What this package contains\\n\\n- `psychiatrypt2.gs` \u2014 merge-friendly Google Apps Script backend module for an OpenAI-powered service.\\n- `js/psychiatry2/` \u2014 reusable client/server-side JavaScript helpers for routing, safety, retrieval, accessibility adaptation, CBT/DBT/neurodivergence support, physical-health support, care planning, and clinician handoff.\\n- `json/psychiatry2/` \u2014 structured support cards, safety rules, routing metadata, scope policy, crisis resource configuration, and a manifest that can be hosted beneath `AI-Brain/json/psychiatry2/`.\\n- `reference_sources/` \u2014 relevant mental-health project source material extracted from the supplied archive. These are **reference-only** and are not executed by the new runtime.\\n- `docs/` \u2014 integration, safety, source-audit, and merge guidance.\\n\\n## Explicit exclusions\\n\\nThe supplied personalized app packages and fake-currency/game-economy systems are not part of this brain. The new runtime does not depend on personal profiles, characters, relationship data, reward currencies, virtual-pet logic, or user-specific identity information.\\n\\n## Deployment layout\\n\\nSuggested GitHub placement:\\n\\n```text\\nAI-Brain/\\n  js/psychiatry2/       <- copy this package's js/psychiatry2 contents\\n  json/psychiatry2/     <- copy this package's json/psychiatry2 contents\\n  backend/psychiatrypt2.gs (optional source copy)\\n```\\n\\nThe backend's default knowledge root points to the public raw GitHub path for `tyrannosaurusdm92/AI-Brain project/main/AI-Brain/json/psychiatry2` and can be overridden with the Apps Script property `PSY2_KNOWLEDGE_BASE_URL`.\\n\\n## Safety and scope\\n\\nThis brain is designed to support, educate, organize, validate, coach skills, and prepare users for professional care. It deliberately avoids claiming to diagnose, prescribe, replace a licensed professional, or decide whether a user is medically safe. High-risk language and emergency physical-health signals route to escalation-first responses.\\n\\n## Required Apps Script properties\\n\\n- `OPENAI_API_KEY` \u2014 required.\\n- `OPENAI_MODEL` \u2014 optional; default is `gpt-5`.\\n- `PSY2_KNOWLEDGE_BASE_URL` \u2014 optional raw GitHub JSON root.\\n- `PSY2_US_988_ENABLED` \u2014 optional; set `true` if your application is serving users in the United States and may display 988.\\n\\n## Third-party code\\n\\nThe `reference_sources/` directory contains third-party projects from the supplied archive. Their licenses and READMEs remain with their source trees where provided. Legacy embedded credentials were removed. Review each project's license before public redistribution or production reuse.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"docs/REFERENCE_SOURCE_POLICY.md\",\"language\":\"md\",\"content\":\"# Reference-source policy\\n\\nThe projects under `reference_sources/` are preserved as source/reference material because they contain useful chatbot architecture, mental-health datasets, embeddings, sentiment tooling, DBT/ADHD structured materials, and psychiatric-assistant experiments. They are **not automatically trusted or executed** by the new brain.\\n\\nReasons include older API conventions, obsolete dependencies, simplistic sentiment-to-advice logic, outdated crisis information in some historical code, and legacy configuration patterns. The new `js/psychiatry2` and `json/psychiatry2` layers supersede those runtime assumptions.\\n\\nCredentials found in legacy source trees were removed or redacted during consolidation.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"docs/SAFETY_ARCHITECTURE.md\",\"language\":\"md\",\"content\":\"# Safety architecture\\n\\nThe active brain uses layered safety instead of a single sentiment score.\\n\\n1. **Local signal detection** runs before model generation. It looks for direct self-harm intent, plans/means language, threats of violence, possible overdose, severe confusion/unresponsiveness, severe breathing problems, severe chest pain/pressure, stroke-like sudden deficits, and other emergency wording.\\n2. **Moderation** is used as an additional classifier, not as the sole crisis detector.\\n3. **Scope policy** prevents the assistant from presenting itself as a doctor, therapist, psychiatrist, or emergency service; diagnosing; recommending medication starts/stops/dose changes; or telling a user that symptoms are definitely benign.\\n4. **Knowledge routing** selects only a small set of relevant support cards so supportive coaching does not drown out safety instructions.\\n5. **Accessibility adaptation** can shorten steps, lower cognitive load, offer text-based alternatives, and adapt exercises for mobility/fatigue/sensory constraints.\\n6. **Human handoff** can create a concise, user-reviewed summary for a clinician without inferring a diagnosis.\\n\\nThe package treats crisis handling as a routing problem, not a conversational style problem. When emergency signals are detected, the output should prioritize immediate connection to local emergency/crisis care over CBT/DBT exercises.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"docs/SOURCE_AUDIT.md\",\"language\":\"md\",\"content\":\"# Source audit\\n\\nIncluded reference projects/directories: Chat-Bot-main, ChatPsychiatrist-master, Chatbot-for-mental-health-main, Chatbot-master, DBT+ADHD Skill Files, Mental-Health-Support-Chatbot-main, MentalHealthBot-master, MindEase-main, Virtual-Psychiatrist-master.\\n\\nExcluded from the consolidation: the personalized application archives and generic prompt/LLM platform archives that were not specifically mental-health support projects.\\n\\nReference files indexed: 861. Reference-source uncompressed bytes: 98,601,062.\\n\\nLargest file-type groups: .json: 277, .py: 136, .html: 125, .ttf: 88, .png: 44, .md: 40, [no-ext]: 24, .js: 22, .txt: 17, .jsonl: 17, .sh: 8, .ipynb: 4.\\n\\nLegacy credential-bearing service-account/config files found during consolidation were removed, and token-like secrets in retained text files were redacted.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Pt2.zip\",\"source_path\":\"docs/MERGE_GUIDE.md\",\"language\":\"md\",\"content\":\"# Merging `psychiatrypt2.gs` into a larger `ai-brain.gs`\\n\\n`psychiatrypt2.gs` intentionally exposes one namespace object, `PsychiatryPt2`, and avoids defining Apps Script's global `doGet`/`doPost` entry points. This prevents collisions when multiple backends are consolidated.\\n\\nA central dispatcher can call:\\n\\n```javascript\\nreturn PsychiatryPt2.handlePost(e);\\n```\\n\\nor directly:\\n\\n```javascript\\nvar result = PsychiatryPt2.chat({\\n  message: body.message,\\n  context: body.context || {},\\n  options: body.options || {}\\n});\\n```\\n\\nRecommended routing key: `module: \\\"psychiatry2\\\"`.\\n\\nKeep secrets in Script Properties. Do not copy an API key into JavaScript or JSON hosted on GitHub.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"README.md\",\"language\":\"md\",\"content\":\"# Unified Psychiatric AI Brain, Part 3\\n\\nThis package is a de-identified support-material brain for an AI backend. It focuses on ADHD, autism-informed support, CBT, DBT, psychiatric and general mental-health support, physical-health support, accessibility, grounding, grief, sleep, relationships, self-care, medication journaling, clinician preparation, and crisis-safe routing.\\n\\n## What it is\\n\\nA structured retrieval and safety layer that can help an AI produce more consistent supportive responses, organize check-ins, coach coping skills, scaffold executive function, respect neurodivergent communication and sensory needs, and prepare information for qualified clinicians.\\n\\n## What it is not\\n\\nIt is not a licensed clinician, diagnosis engine, prescription engine, emergency service, or replacement for a therapist, psychiatrist, physician, pharmacist, crisis team, or written medical/safety plan. The code intentionally blocks medication dose changes and routes clear immediate danger away from ordinary chatbot flow.\\n\\n## GitHub placement\\n\\nCopy the package contents into `AI-Brain/` so these paths exist:\\n\\n- `AI-Brain/backend/psychiatrypt3.gs`\\n- `AI-Brain/js/*.js`\\n- `AI-Brain/json/core/*.json`\\n- `AI-Brain/json/indexes/*.json`\\n- `AI-Brain/json/scenarios/<domain>/part-###.json`\\n- `AI-Brain/json/skills/skill_cards.json`\\n- `AI-Brain/json/knowledge/*.json`\\n\\nThe Apps Script backend defaults to the raw `main/AI-Brain` GitHub path and can be overridden with the `PT3_GITHUB_RAW_BASE` Script Property.\\n\\n## Apps Script properties\\n\\n- `OPENAI_API_KEY`: required for OpenAI model calls.\\n- `OPENAI_MODEL`: optional; defaults to `gpt-5`.\\n- `PT3_GITHUB_RAW_BASE`: optional raw GitHub base override.\\n- `PT3_MAX_CONTEXT_CHARS`: optional context cap; default `18000`.\\n\\n## Merge-safe backend\\n\\nThe file does not define `doGet()` or `doPost()`. Its public entry points are:\\n\\n- `psychiatrypt3Health()`\\n- `psychiatrypt3Handle(payload)`\\n- `psychiatrypt3Ask(message, options)`\\n- `psychiatrypt3BuildContext(message, options)`\\n\\nThat makes it easier to combine later into a larger `ai-brain.gs` without duplicate web-app entry points.\\n\\n## Corpus design\\n\\nThe large scenario corpus is composed of de-identified routing records and has been sharded into small GitHub-friendly JSON files. Persona fields, personal names, private relationship labels, appearance data, pet behavior, game/economy logic, private images, and reward/currency systems are excluded.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"backend/psychiatrypt3.gs\",\"language\":\"gs\",\"content\":\"/**\\n * psychiatrypt3.gs\\n * Unified psychiatric / mental-health / neurodiversity / physical-health support module.\\n *\\n * Designed to be merged later into a larger Apps Script backend without owning doGet/doPost.\\n * Public entry points are prefixed with psychiatrypt3 or PT3_ to avoid collisions.\\n *\\n * Script Properties:\\n *   OPENAI_API_KEY       required for model calls\\n *   OPENAI_MODEL         optional, defaults to gpt-5\\n *   PT3_GITHUB_RAW_BASE  optional override of the raw AI-Brain base\\n *   PT3_MAX_CONTEXT_CHARS optional, defaults to 18000\\n */\\n\\nvar PT3_VERSION = \\\"3.0.0\\\";\\nvar PT3_DEFAULT_RAW_BASE = \\\"https://raw.githubusercontent.com/tyrannosaurusdm92/AI-Brain project/main/AI-Brain\\\";\\nvar PT3_OPENAI_URL = \\\"https://api.openai.com/v1/responses\\\";\\n\\nfunction psychiatrypt3Health() {\\n  return {\\n    ok: true,\\n    module: \\\"psychiatrypt3\\\",\\n    version: PT3_VERSION,\\n    capabilities: [\\\"adhd\\\",\\\"autism\\\",\\\"cbt\\\",\\\"dbt\\\",\\\"psychiatric_support\\\",\\\"physical_health\\\",\\\"general_mental_health\\\"],\\n    apiKeyConfigured: !!PT3_getProperty_(\\\"OPENAI_API_KEY\\\")\\n  };\\n}\\n\\nfunction psychiatrypt3Handle(payload) {\\n  payload = payload || {};\\n  if (typeof payload === \\\"string\\\") payload = { message: payload };\\n  var message = String(payload.message || payload.input || \\\"\\\").trim();\\n  if (!message) return { ok:false, error:\\\"message_required\\\", version:PT3_VERSION };\\n\\n  var safety = PT3_classifySafety_(message);\\n  var domains = PT3_classifyDomains_(message);\\n  if (safety.level === \\\"immediate\\\") {\\n    return {\\n      ok: true,\\n      version: PT3_VERSION,\\n      mode: \\\"deterministic_safety\\\",\\n      safety: safety,\\n      domains: domains,\\n      text: PT3_immediateSafetyMessage_(payload.country || payload.locale || \\\"\\\")\\n    };\\n  }\\n\\n  var context = psychiatrypt3BuildContext(message, {\\n    domains: domains,\\n    safety: safety,\\n    maxContextChars: payload.maxContextChars\\n  });\\n\\n  if (payload.contextOnly === true) {\\n    return { ok:true, version:PT3_VERSION, mode:\\\"context_only\\\", safety:safety, domains:domains, context:context };\\n  }\\n\\n  var modelResult = PT3_callOpenAI_(message, context, payload);\\n  return {\\n    ok: true,\\n    version: PT3_VERSION,\\n    mode: \\\"openai_responses\\\",\\n    model: modelResult.model,\\n    safety: safety,\\n    domains: domains,\\n    text: modelResult.text,\\n    responseId: modelResult.responseId || null,\\n    contextMeta: context.meta\\n  };\\n}\\n\\nfunction psychiatrypt3Ask(message, options) {\\n  options = options || {};\\n  options.message = message;\\n  return psychiatrypt3Handle(options);\\n}\\n\\nfunction psychiatrypt3BuildContext(message, options) {\\n  options = options || {};\\n  var domains = options.domains || PT3_classifyDomains_(message);\\n  var safety = options.safety || PT3_classifySafety_(message);\\n  var policy = PT3_fetchJson_(\\\"json/core/system_policy.json\\\");\\n  var style = PT3_fetchJson_(\\\"json/core/response_style.json\\\");\\n  var skillCards = PT3_fetchJson_(\\\"json/skills/skill_cards.json\\\");\\n  var knowledge = PT3_fetchJson_(\\\"json/knowledge/support_knowledge.json\\\");\\n  var domainIndex = PT3_fetchJson_(\\\"json/indexes/domain_index.json\\\");\\n\\n  var scenarioPool = [];\\n  for (var i=0; i<domains.length; i++) {\\n    var shard = PT3_chooseShard_(domainIndex, domains[i], message);\\n    if (!shard) continue;\\n    var shardData = PT3_fetchJson_(shard.path);\\n    if (shardData && shardData.items) scenarioPool = scenarioPool.concat(shardData.items);\\n  }\\n\\n  var selectedSkills = PT3_rankItems_((skillCards && skillCards.skills) || [], message, 8);\\n  var selectedKnowledge = PT3_rankItems_((knowledge && knowledge.items) || [], message, 8);\\n  var selectedScenarios = PT3_rankItems_(scenarioPool, message, 12);\\n\\n  var context = {\\n    policy: policy,\\n    responseStyle: style,\\n    safety: safety,\\n    domains: domains,\\n    selectedSkills: selectedSkills,\\n    selectedKnowledge: selectedKnowledge,\\n    selectedScenarios: selectedScenarios,\\n    meta: { version:PT3_VERSION, scenarioCandidates:scenarioPool.length }\\n  };\\n  return PT3_capContext_(context, options.maxContextChars);\\n}\\n\\nfunction PT3_callOpenAI_(message, context, payload) {\\n  var key = PT3_getProperty_(\\\"OPENAI_API_KEY\\\");\\n  if (!key) throw new Error(\\\"OPENAI_API_KEY is not configured in Apps Script Properties.\\\");\\n  var model = String(payload.model || PT3_getProperty_(\\\"OPENAI_MODEL\\\") || \\\"gpt-5\\\");\\n  var instructions = [\\n    \\\"You are a supportive mental-health and health-navigation assistant operating under the supplied policy.\\\",\\n    \\\"You are not a licensed clinician or emergency service. Do not diagnose or prescribe.\\\",\\n    \\\"Use the retrieved skills and scenarios as support material, not as proof of a diagnosis.\\\",\\n    \\\"If psychosis, paranoia, hallucinations, or mania-like content appears, validate distress without confirming implausible beliefs as fact.\\\",\\n    \\\"Never advise starting, stopping, tapering, calculating, or changing medication doses.\\\",\\n    \\\"If the user's condition appears more urgent than the classifier indicates, escalate to real-world human or emergency help.\\\",\\n    \\\"Respect disability, sensory, AAC, mobility, fatigue, pain, and communication constraints.\\\",\\n    \\\"Prefer one to three concrete next steps when the person sounds overwhelmed.\\\",\\n    \\\"RETRIEVED SUPPORT CONTEXT:\\\",\\n    JSON.stringify(context)\\n  ].join(\\\"\\\\n\\\");\\n\\n  var req = {\\n    model: model,\\n    instructions: instructions,\\n    input: [{ role:\\\"user\\\", content:[{ type:\\\"input_text\\\", text:message }] }]\\n  };\\n  if (payload.previous_response_id) req.previous_response_id = String(payload.previous_response_id);\\n\\n  var r = UrlFetchApp.fetch(PT3_OPENAI_URL, {\\n    method: \\\"post\\\",\\n    contentType: \\\"application/json\\\",\\n    headers: { Authorization: \\\"Bearer \\\" + key },\\n    payload: JSON.stringify(req),\\n    muteHttpExceptions: true\\n  });\\n  var code = r.getResponseCode();\\n  var text = r.getContentText();\\n  var data;\\n  try { data = JSON.parse(text); } catch (e) { throw new Error(\\\"OpenAI returned non-JSON HTTP \\\" + code); }\\n  if (code < 200 || code >= 300) {\\n    var msg = data && data.error && data.error.message ? data.error.message : (\\\"OpenAI HTTP \\\" + code);\\n    throw new Error(msg);\\n  }\\n  return { model:model, text:PT3_extractOutputText_(data), responseId:data.id || null, raw:data };\\n}\\n\\nfunction PT3_extractOutputText_(data) {\\n  if (data && typeof data.output_text === \\\"string\\\") return data.output_text;\\n  var parts = [];\\n  var output = (data && data.output) || [];\\n  for (var i=0; i<output.length; i++) {\\n    var content = output[i].content || [];\\n    for (var j=0; j<content.length; j++) {\\n      if (content[j] && content[j].type === \\\"output_text\\\" && content[j].text) parts.push(content[j].text);\\n    }\\n  }\\n  return parts.join(\\\"\\\\n\\\");\\n}\\n\\nfunction PT3_classifySafety_(message) {\\n  var t = String(message || \\\"\\\");\\n  var flags = {\\n    suicide: /\\\\b(kill myself|end my life|suicide|suicidal|want to die|can't stay safe|cannot stay safe|attempted suicide)\\\\b/i.test(t),\\n    violence: /\\\\b(kill (him|her|them|someone)|hurt (him|her|them|someone)|murder|shoot|stab)\\\\b/i.test(t),\\n    overdose: /\\\\b(overdose|poisoned|poisoning|took too many|dangerous ingestion)\\\\b/i.test(t),\\n    medical: /\\\\b(can't breathe|cannot breathe|severe trouble breathing|unconscious|won't wake|seizure|stroke|face droop|one-sided weakness|anaphylaxis|severe allergic reaction|crushing chest|severe chest pressure|uncontrolled bleeding)\\\\b/i.test(t),\\n    psychosis: /\\\\b(hearing voices|seeing things|hallucination|paranoia|paranoid|being watched|being followed|thought broadcasting|command voice)\\\\b/i.test(t),\\n    mania: /\\\\b(no sleep for days|haven't slept for days|have not slept for days|invincible|limitless energy|racing thoughts|grandiose)\\\\b/i.test(t),\\n    medication: /\\\\b(stop my medication|stop my meds|change my dose|increase my dose|decrease my dose|taper|missed dose|side effect|withdrawal)\\\\b/i.test(t)\\n  };\\n  var level=\\\"routine\\\", route=\\\"support_and_skills\\\";\\n  if (flags.suicide || flags.violence || flags.overdose || flags.medical) { level=\\\"immediate\\\"; route=\\\"deterministic_emergency_route\\\"; }\\n  else if (flags.psychosis || flags.mania) { level=\\\"urgent\\\"; route=\\\"reality_grounded_professional_bridge\\\"; }\\n  else if (flags.medication) { level=\\\"watch\\\"; route=\\\"medication_boundary\\\"; }\\n  return { schema:\\\"psychiatrypt3.safety.v1\\\", level:level, route:route, flags:flags };\\n}\\n\\nfunction PT3_immediateSafetyMessage_(country) {\\n  var base = \\\"This may be an immediate safety or medical emergency. Contact local emergency services now, involve a nearby trusted person if possible, and follow any existing safety or emergency plan. Do not delay emergency help to continue a chatbot exercise.\\\";\\n  var c = String(country || \\\"\\\").toUpperCase();\\n  if (c === \\\"US\\\" || c === \\\"USA\\\" || c.indexOf(\\\"UNITED STATES\\\") >= 0) base += \\\" If the crisis is suicidal or emotional and emergency medical response is not required, 988 is an additional U.S. crisis option.\\\";\\n  return base;\\n}\\n\\nfunction PT3_classifyDomains_(message) {\\n  var t=String(message||\\\"\\\");\\n  var map=[\\n    [\\\"adhd\\\", /\\\\b(adhd|executive dysfunction|time blind|procrastinat|can't start|cannot start|focus|distract|working memory|task initiation)\\\\b/i],\\n    [\\\"autism\\\", /\\\\b(autis|sensory|meltdown|shutdown|masking|burnout|aac|nonverbal|nonspeaking|transition)\\\\b/i],\\n    [\\\"cbt\\\", /\\\\b(cbt|thought record|cognitive distortion|automatic thought|behavioral activation|worry|avoidance|exposure)\\\\b/i],\\n    [\\\"dbt\\\", /\\\\b(dbt|wise mind|tipp|stop skill|dear man|give skill|fast skill|opposite action|radical acceptance|check the facts|distress tolerance|chain analysis)\\\\b/i],\\n    [\\\"psychiatric_support\\\", /\\\\b(psychiatr|psychosis|hallucinat|paranoi|mania|manic|depression|anxiety|trauma|medication|prescriber|therapist|clinician)\\\\b/i],\\n    [\\\"physical_health\\\", /\\\\b(pain|fatigue|symptom|doctor|medical|mobility|wheelchair|oxygen|breathing|glucose|blood sugar|seizure|allergy|hydration|nausea|dizziness)\\\\b/i],\\n    [\\\"general_mental_health\\\", /\\\\b(grief|grounding|dissociat|sad|lonely|overwhelm|panic|relationship|sleep|self care|stress)\\\\b/i]\\n  ];\\n  var hits=[]; for(var i=0;i<map.length;i++) if(map[i][1].test(t)) hits.push(map[i][0]);\\n  if(!hits.length) hits=[\\\"general_mental_health\\\"];\\n  return hits.slice(0,4);\\n}\\n\\nfunction PT3_chooseShard_(index, domain, message) {\\n  var info=index && index.domains && index.domains[domain];\\n  if(!info || !info.shards || !info.shards.length) return null;\\n  var n=PT3_hash_(domain+\\\"|\\\"+message) % info.shards.length;\\n  return info.shards[n];\\n}\\n\\nfunction PT3_hash_(text) {\\n  var bytes=Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(text||\\\"\\\"), Utilities.Charset.UTF_8);\\n  return ((bytes[0]&255)<<24 | (bytes[1]&255)<<16 | (bytes[2]&255)<<8 | (bytes[3]&255)) >>> 0;\\n}\\n\\nfunction PT3_tokenize_(text) {\\n  var m=String(text||\\\"\\\").toLowerCase().match(/[a-z0-9_'-]{3,}/g) || [];\\n  var out=[], seen={};\\n  for(var i=0;i<m.length && out.length<40;i++){ if(!seen[m[i]]){seen[m[i]]=1;out.push(m[i]);} }\\n  return out;\\n}\\n\\nfunction PT3_rankItems_(items, message, limit) {\\n  var tokens=PT3_tokenize_(message);\\n  var scored=(items||[]).map(function(x){\\n    var blob=JSON.stringify(x).toLowerCase(), s=0;\\n    for(var i=0;i<tokens.length;i++) if(blob.indexOf(tokens[i])>=0) s++;\\n    return {x:x,s:s};\\n  });\\n  scored.sort(function(a,b){ return b.s-a.s; });\\n  return scored.slice(0,limit||8).map(function(r){return r.x;});\\n}\\n\\nfunction PT3_capContext_(context, requested) {\\n  var cap=Number(requested || PT3_getProperty_(\\\"PT3_MAX_CONTEXT_CHARS\\\") || 18000);\\n  if(!isFinite(cap) || cap<6000) cap=6000;\\n  var txt=JSON.stringify(context);\\n  if(txt.length>cap) context.selectedScenarios=context.selectedScenarios.slice(0,5);\\n  txt=JSON.stringify(context);\\n  if(txt.length>cap) context.selectedKnowledge=context.selectedKnowledge.slice(0,5);\\n  txt=JSON.stringify(context);\\n  if(txt.length>cap) context.selectedSkills=context.selectedSkills.slice(0,4);\\n  txt=JSON.stringify(context);\\n  if(txt.length>cap) context.selectedScenarios=context.selectedScenarios.slice(0,3);\\n  context.meta.contextChars=JSON.stringify(context).length;\\n  context.meta.contextCap=cap;\\n  return context;\\n}\\n\\nfunction PT3_fetchJson_(path) {\\n  var base=String(PT3_getProperty_(\\\"PT3_GITHUB_RAW_BASE\\\") || PT3_DEFAULT_RAW_BASE).replace(/\\\\/$/,\\\"\\\");\\n  var url=base+\\\"/\\\"+String(path||\\\"\\\").replace(/^\\\\//,\\\"\\\");\\n  var cache=CacheService.getScriptCache();\\n  var key=\\\"pt3:\\\"+Utilities.base64EncodeWebSafe(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,url,Utilities.Charset.UTF_8)).substring(0,40);\\n  var hit=cache.get(key);\\n  if(hit){ try{return JSON.parse(hit);}catch(e){} }\\n  var r=UrlFetchApp.fetch(url,{muteHttpExceptions:true,headers:{\\\"Accept\\\":\\\"application/json\\\"}});\\n  var code=r.getResponseCode(); if(code<200||code>=300) throw new Error(\\\"AI-Brain fetch failed HTTP \\\"+code+\\\" for \\\"+path);\\n  var text=r.getContentText();\\n  try{ if(text.length<95000) cache.put(key,text,21600); }catch(e){}\\n  return JSON.parse(text);\\n}\\n\\nfunction PT3_getProperty_(name) {\\n  return PropertiesService.getScriptProperties().getProperty(name);\\n}\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"docs/AUDIT.md\",\"language\":\"md\",\"content\":\"# Build audit\\n\\n- Version: 3.0.0\\n- Files before archive: 878\\n- Scenario domains: 17\\n- Scenario records: 254,971\\n- Scenario data is de-identified and persona-only fields were removed.\\n- Personal photos, appearance/model assets, pet/avatar behavior, private profile records, games, stores, rewards, and economy mechanics were excluded.\\n- Explicit identity-name scan: PASS.\\n- Safety boundary includes no diagnosis, no prescribing or medication-dose changes, no delusion reinforcement, and deterministic immediate-danger escalation.\\n- GitHub layout: compatible with `AI-Brain/js`, `AI-Brain/json`, and `AI-Brain/backend`.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"docs/INTEGRATION.md\",\"language\":\"md\",\"content\":\"# Integration notes\\n\\n1. Upload this package under the repository's `AI-Brain/` directory.\\n2. Copy or merge `backend/psychiatrypt3.gs` into the Google Apps Script backend project.\\n3. Set `OPENAI_API_KEY` in Apps Script Script Properties, not in public code.\\n4. Optionally set `OPENAI_MODEL`, `PT3_GITHUB_RAW_BASE`, and `PT3_MAX_CONTEXT_CHARS`.\\n5. Call `psychiatrypt3Health()` to confirm configuration.\\n6. Call `psychiatrypt3Handle({message:\\\"...\\\", country:\\\"US\\\"})` for a complete response, or `psychiatrypt3BuildContext(...)` if a larger master backend will make the model call itself.\\n\\nThe context builder selects only a small scenario shard per routed domain. This avoids attempting to load the entire large corpus into Apps Script or a single model prompt.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"docs/OPENAI_INTEGRATION.md\",\"language\":\"md\",\"content\":\"# OpenAI integration\\n\\n`psychiatrypt3.gs` uses the OpenAI Responses API endpoint from a server-side Google Apps Script request. The API key is read from the `OPENAI_API_KEY` Script Property. The helper intentionally does not place the key in frontend JavaScript or repository files.\\n\\nThe request sends a bounded retrieved context plus the user's message. The backend parses `output` content for `output_text` items and can optionally continue a conversation using `previous_response_id`.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"docs/SAFETY.md\",\"language\":\"md\",\"content\":\"# Safety architecture\\n\\nThe package uses deterministic pre-model checks for immediate danger, separates support from diagnosis/treatment, blocks medication-changing behavior, avoids reinforcing delusions or mania-driven certainty, and encourages real-world professional or emergency care when indicated.\\n\\nPhysical-health support is intentionally conservative: symptom journaling, accessibility planning, basic-needs prompts, clinician preparation, and adherence to an existing written plan are supported; diagnosis and individualized medication/device dosing are not.\\n\\nThe scenario corpus is decision-support metadata, not clinical ground truth. A route match must never be treated as proof that a diagnosis is present.\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_pt3.zip\",\"source_path\":\"js/README.md\",\"language\":\"md\",\"content\":\"# JavaScript helpers\\n\\nThese helpers are intentionally provider-neutral and contain no API key. `openai-responses-client.js` is for server-side JavaScript only; never expose a secret key in browser code. The Google Apps Script backend in `backend/psychiatrypt3.gs` is the primary integration surface for this package.\\n\"}]}";
